/* A classroom reconstruction using modern U/T notation, not Gosset's original dataset. */
(()=>{'use strict';const M=TrialStoryModel,blue='#789db5',orange='#bf9250',green='#7e9f79',cache=new WeakMap();
const f=(v,d=2)=>Number(v).toFixed(d),button=(action,label,attrs='')=>`<button data-action="${action}" ${attrs}>${label}</button>`;
function summary(records){let out=cache.get(records);if(out?.count===records.length)return out;const pairs=records.map(M.pair),lo=-5.5,width=.25,bins=44,z=Array(bins).fill(0),r=Array(bins).fill(0);let zOutside=0,rOutside=0,zTails=0,rTails=0;
 for(const p of pairs){for(const [key,counts] of [['z',z],['r',r]]){const i=Math.floor((p[key]-lo)/width);if(i>=0&&i<bins)counts[i]++;else if(key==='z')zOutside++;else rOutside++;}if(Math.abs(p.z)>=2)zTails++;if(Math.abs(p.r)>=2)rTails++;}
 out={count:pairs.length,pairs,z,r,lo,width,zOutside,rOutside,zTails,rTails};cache.set(records,out);return out;
}
function discoveryMarkup(state){const e=state.e,s=summary(e.runs),last=s.pairs.at(-1);
 let html=(s.count<1000?`<div class="activity-row">${button('variance','抽取四个小区，计算一次','class="primary"')}</div>`:'')+`<p class="activity-meta">已抽样 ${s.count} 组 · 每组4个小区</p>`;
 if(last)html+=`<div class="samples-chips">${e.runs.at(-1).map(v=>`<span>${f(v,1)}</span>`).join('')}</div>${e.normalCompared?`<div class="paired-results"><div><small>已知分母 σ/√n</small><b>U＝${f(last.z)}</b></div><div><small>估计分母 s/√n（样本标准误差）</small><b>T＝${f(last.r)}</b></div></div>`:`<div class="formula-card">T＝(${f(last.mean,1)} − 500) / ${f(last.estimatedSE)}＝${f(last.r)}<small>样本均值 x̄＝${f(last.mean,1)}　样本标准误差 s/√4＝${f(last.estimatedSE)}</small></div>`}`;
 if(e.manualRuns>=3&&s.count<1000)html+=`<div class="activity-row">${button('discovery-many','继续抽样，收集1000个结果','class="primary"')}</div>`;
 if(s.count>=1000&&!e.histogramShown)html+=`<div class="activity-row">${button('discovery-histogram','按区间计数，生成频率条形图','class="primary"')}</div>`;
 if(e.histogramShown&&!e.tRevealed)html+=`<p class="activity-meta">条形图来自刚才1000次抽样的结果。</p><div class="activity-row">${button('reveal-t','查看这类结果的理论曲线','class="primary"')}</div>`;
 if(e.tRevealed&&!e.normalCompared)html+=`<p class="activity-meta">条形图描述抽样频率，橙线描述这类结果的理论分布。</p><div class="activity-row">${button('compare-normal','再与标准正态分布比较','class="primary"')}</div>`;
 if(e.normalCompared&&!e.tailCompared)html+=`<div class="teacher-note">±2之外：<br>蓝色U ${f(s.zTails/s.count*100,1)}%　橙色T ${f(s.rTails/s.count*100,1)}%<br>哪一套结果的尾部更多？</div><div class="activity-row">${button('discovery-tail','已知分母的U','data-value="z"')}${button('discovery-tail','估计分母后的T','data-value="r"')}</div>`;
 if(e.tailCompared&&!e.gossetShown)html+=`<div class="teacher-note">用样本标准误差作分母，尾部比标准正态更厚。求概率时，需要用这条分布。</div><div class="activity-row">${button('name-t','这条分布是谁发现的？','class="primary"')}</div>`;
 if(e.gossetShown)html+=`<div class="teacher-note">Gosset研究了这种小样本分布，1908年以 <b>Student</b> 为笔名发表。它后来被称为 <b>Student t分布</b>。</div><div class="df-example"><table><tr><th>产量</th><td>520</td><td>540</td><td>560</td><td>580</td></tr><tr><th>减去均值550</th><td>−30</td><td>−10</td><td>＋10</td><td class="dependent">＋30</td></tr></table><p>四个偏差的和为0。前三个合计−30，第4个只能是＋30。</p><p>能自由变化的偏差只有3个，所以 <b>df＝4−1＝3</b>。</p></div>`;
 return html;
}
function deviationMarkup(d){return d.map((v,i)=>`<span class="${i===3?'dependent':''}">${v>0?'+':''}${v}</span>`).join('')+'<b>＝0</b>';}
function discoveryCopy(state){const e=state.e;if(e.gossetShown)return {title:'Gosset与Student t分布',badges:['样本标准误差作分母','Student t分布','n＝4 · df＝3'],note:'同样来自正态总体；换了估计分母，统计量的分布就改变了。',hint:'用固定例子看自由度，再选择求概率应使用的分布。'};if(e.normalCompared)return {title:'再与标准正态分布比较',badges:['蓝：已知分母 → U','橙：样本标准误差 → T'],note:'比较±2之外的结果，看看估计分母后尾部有什么变化。',hint:'先比较尾部，再揭示这条分布的发现者和名称。'};if(e.tRevealed)return {title:'频率条形图，再看理论曲线',badges:['1000次抽样','样本标准误差作分母'],note:'条形图来自抽样；橙线是独立正态观测条件下的理论分布。',hint:'先观察橙色曲线，再叠加标准正态作比较。'};if(e.histogramShown)return {title:'结果按区间堆成条形图',badges:['每组4个小区','已抽样1000组','先看实际频率'],note:'柱子按频率密度绘制；每根柱子的面积等于该区间频率。',hint:'先看抽样形成的条形图，再查看对应的理论曲线。'};return {title:'先抽样，收集每次计算的结果',badges:['每组4个小区','均值与样本标准误差','每组留下一个T值'],note:'先抽样，再统计频率；这里还没有放入理论分布曲线。',hint:e.manualRuns<3?'先逐组抽样至少3次。':'继续收集1000个结果，再按区间计数。'};}
function comparisonMarkup(state,n){return `<p class="activity-meta">我们只看两式的分母：同一个n下，已知的σ/√n是定值，估计的s/√n会随样本变化。</p><div class="comparison-current">重复数 n＝<output id="n-out">${n}</output></div><div class="range-presets">${[4,10,30,100].map(v=>button('compare-n',String(v),`data-n="${v}" class="${v===n?'active':''}"`)).join('')}</div><div id="comparison-numbers">${comparisonNumbers(M.convergence(n))}</div><div class="teacher-note">先看左边U式里，分子原有的方差怎样被除掉；再看T额外带着的σ/s。换几个n，只比较下面两条曲线的尾部即可。</div>`;}
function comparisonNumbers(c){return `<div class="simple-probabilities"><p>自由度 df＝${c.n}−1＝<b>${c.df}</b></p><p>同一位置2的右尾：</p><div><span class="z-text">标准正态 ${f(c.zTail*100,2)}%</span><span class="t-text">t分布 ${f(c.tTail*100,2)}%</span></div></div>`;}
const math=body=>`<math xmlns="http://www.w3.org/1998/Math/MathML" display="block">${body}</math>`,frac=(a,b)=>`<mfrac>${a}${b}</mfrac>`,xbar='<mover><mi>X</mi><mo>¯</mo></mover>',mu='<mi>μ</mi>',sigma='<mi>σ</mi>',sigma2='<msup><mi>σ</mi><mn>2</mn></msup>',rootN='<msqrt><mi>n</mi></msqrt>',delta=`<mrow>${xbar}<mo>−</mo>${mu}</mrow>`;
function mathComparisonMarkup(n){const tvar=(n-1)/(n-3);return `<section class="math-card z-proof"><h3>U：已知分母，固定n时它不波动</h3>${math(`<mrow>${xbar}<mo>∼</mo><mi>N</mi><mo>(</mo>${mu}<mo>,</mo>${frac(sigma2,'<mi>n</mi>')}<mo>)</mo></mrow>`)}${math(`<mrow><mi>U</mi><mo>=</mo>${frac(delta,frac(sigma,rootN))}</mrow>`)}<p>除以一个定值，方差就除以这个定值的平方：</p>${math(`<mrow><mi>Var</mi><mo>(</mo><mi>U</mi><mo>)</mo><mo>=</mo>${frac(sigma2,'<mi>n</mi>')}<mo>÷</mo>${frac(sigma2,'<mi>n</mi>')}<mo>=</mo><mn>1</mn></mrow>`)}<div class="proof-result">仍是正态，中心为0、方差为1<br><b>U ∼ N(0,1)</b>，形状不再随n改变。</div></section><section class="math-card t-proof"><h3>T：分母靠样本估计，会波动</h3>${math(`<mrow><mi>T</mi><mo>=</mo>${frac(delta,frac('<mi>s</mi>',rootN))}<mo>=</mo><mi>U</mi><mo>×</mo>${frac(sigma,'<mi>s</mi>')}</mrow>`)}<p>每换一批样本，s就可能不同。<br>多出来的 <b>σ/s</b> 仍然是随机的。</p>${math('<mrow><mi>T</mi><mo>∼</mo><msub><mi>t</mi><mi>ν</mi></msub><mo>,</mo><mi>ν</mi><mo>=</mo><mi>n</mi><mo>−</mo><mn>1</mn></mrow>')}<p>从t分布的方差结果，也能直接看到n：</p>${math(`<mrow><mi>Var</mi><mo>(</mo><mi>T</mi><mo>)</mo><mo>=</mo>${frac('<mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow>','<mrow><mi>n</mi><mo>−</mo><mn>3</mn></mrow>')}<mspace width=".7em"/><mtext>（n＞3）</mtext></mrow>`)}<div class="proof-result">n＝${n}：U的方差＝1，T的方差≈${f(tvar)}<br>n增多，s的估计更稳定，T逐渐接近U。</div></section><section class="math-card math-curves"><h3>只比较两条曲线：<span class="z-text">标准正态</span>与<span class="t-text">t分布（df＝${n-1}）</span></h3><div id="comparison-curve-host"></div></section>`;}
function axis(w){const X=x=>x*12/11,Y=p=>p*7.5;w.line([[-6.1,0,0],[6.2,0,0]],'#91a081',1);for(const x of [-4,-2,0,2,4])w.label([X(x),-.3,0],String(x),{size:11,color:'#778b68'});for(const x of [-2,2])w.line([[X(x),0,0],[X(x),3.3,0]],'#c0cbb2',.8,{dash:[3,5]});return {X,Y};}
function discovery(w,v){w.extent=16;w.target=w.width<600?3:1.7;const e=v.session.e,s=summary(e.runs),n=Math.max(1,s.count),hist=e.histogramShown,last=s.pairs.at(-1);
 Object.assign(w.canvas.dataset,{discoveryCount:String(s.count),histogramVisible:String(hist),tCurveVisible:String(e.tRevealed),normalCurveVisible:String(e.normalCompared),discoveryNamed:String(e.gossetShown),discoveryStage:e.gossetShown?'named':e.normalCompared?'comparison':e.tRevealed?'curve':hist?'histogram':'sampling',discoveryOutside:String(s.rOutside+(e.normalCompared?s.zOutside:0))});
 if(!hist){const values=e.runs.at(-1);
  for(let i=0;i<4;i++){const x=-4.5+i*3;w.box(x,.1,0,2.2,.08,1.55,'#b4bf90');for(let j=0;j<2;j++)MaizeShoot.draw(w,{x:x-.45+j*.9,y:.19,z:0,height:1,stage:'mature',seed:71+i*3+j,detail:'low'});w.label([x,2,0],values?f(values[i],1):'？',{size:16,color:'#7b895b',pill:true});w.label([x,-.25,0],`小区${i+1}`,{size:11,color:'#7a8d63'});}
  w.label([0,3.5,0],s.count?`第${s.count}组：四个产量 → 一个T值`:'先抽取四个小区',{size:14,color:'#66815c',pill:true});
  w.line([[-5.7,-1.1,0],[5.7,-1.1,0]],'#b5c3a4',1);for(const p of s.pairs.slice(-40))w.dot([Math.max(-5.4,Math.min(5.4,p.r)),-1.05,0],.055,orange);
  w.label([0,-1.6,0],last?`本组T＝${f(last.r)} · 已收集${s.count}个结果`:'每组只留下一个标准化结果',{size:12,color:orange,pill:true});return;
 }
 const {X,Y}=axis(w);
 for(let i=0;i<s.r.length;i++){const x=s.lo+i*s.width,bw=s.width*12/11,series=e.normalCompared?[[s.r,orange,.035],[s.z,blue,-.035]]:[[s.r,orange,0]];for(const [counts,color,dz] of series){const height=counts[i]/(n*s.width)*7.5*(v.discoveryVisual??1);if(height)w.box(X(x+s.width/2),0,dz,bw,height,.035,color,{alpha:.43});}}
 const line=(fn,color,dash=[])=>w.line(Array.from({length:181},(_,i)=>{const x=-5.5+i/180*11;return [X(x),Y(fn(x)),0]}),color,1.9,{dash});
 if(e.tRevealed)line(x=>StudentTMath.pdf(x,3),orange);if(e.normalCompared)line(NormalMath.pdf,blue,[4,4]);
 w.label([0,3.85,0],e.gossetShown?'Student t分布 · df＝3':e.normalCompared?'估计分母的结果，与标准正态比较':e.tRevealed?'频率条形图 → 理论曲线':'1000次抽样 → 频率条形图',{size:13,color:'#77865e',pill:true});
 if(e.normalCompared){w.label([-3,-.8,0],`蓝色U：±2外 ${f(s.zTails/n*100,1)}%`,{size:11,color:blue,pill:true});w.label([3,-.8,0],`橙色T：±2外 ${f(s.rTails/n*100,1)}%`,{size:11,color:orange,pill:true});}else w.label([0,-.85,0],'每根柱子的面积＝该区间的抽样频率',{size:11,color:'#9c8656',pill:true});
 w.label([-5.4,3.35,0],'频率密度',{size:10,color:'#82916e'});
 if(s.rOutside)w.label([0,-1.35,0],`视窗外${s.rOutside}个T结果仍计入尾部频率`,{size:10,color:'#859171'});
}
function dashboardMarkup(state){const e=state.e,data=M.stats(M.noisy),choice=state.answers.challenge,ok=M.correct(state,'challenge');return `<section class="summary-card summary-field"><h3>① 收获新一批四个小区</h3><div id="summary-field-host"></div><div class="summary-yields">${M.noisy.map((v,i)=>button('new-plot',e.newHarvest.includes(i)?`重复${i+1} · ${v}`:`收获重复${i+1}`,`data-plot="${i}" ${e.newHarvest.includes(i)?'disabled class="collected"':''}`)).join('')}</div><small>亩产单位：公斤/亩 · 小区图可拖动旋转</small></section><section class="summary-card"><h3>② 平均值与标准误差</h3>${e.noisy?`<div class="summary-stat"><span>x̄＝${f(data.mean,0)}</span><span>s＝${f(data.s)}</span><span>SE＝${f(data.se)}</span></div><p>均值仍为550；四个小区更分散。</p><p>前一批SE≈12.91<br>这一批SE≈25.82</p>`:`<p>先完成四个小区的收获。</p>${button('noisy','计算本批均值和标准误差',`${e.newHarvest.length<4?'disabled':''} class="primary"`)}`}</section><section class="summary-card summary-probability"><h3>③ 在t分布上找位置与概率</h3><canvas id="summary-curve" aria-label="新一批试验的t分布与右尾概率"></canvas><div class="summary-prob-label">${e.noisy?`t＝(550−500)/25.82≈1.94<br>df＝3，右尾p≈${f(data.p,3)}（延伸至＋∞）`:'用这批数据的SE换成t坐标，再计算右尾面积。'}</div></section><section class="summary-card summary-conclusion"><h3>④ 根据概率作出结论</h3>${e.noisy?`<div class="summary-comparison">p≈${f(data.p,3)} ＞ α＝0.05</div><p>${M.steps[14].question}</p><div class="summary-choices">${M.steps[14].options.map(([id,text])=>button('summary-answer',text,`data-value="${id}" class="${choice===id?(ok?'correct':'wrong'):''}" ${ok?'disabled':''}`)).join('')}</div>${choice?`<p class="summary-result">${ok?'尚未发现显著提高的证据。平均值相同，分散程度不同，结论可能不同。':'请再比较右尾概率与0.05。'}</p>`:''}`:'先用本批数据算出概率，再和试验前约定的0.05比较。'}</section>`;}
function paintDashboard(canvas,state){if(!canvas)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;const dpr=Math.min(devicePixelRatio||1,2),w=r.width,h=r.height;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);const data=M.stats(M.noisy),X=x=>25+(x+4.5)/9*(w-45),Y=p=>h-24-p*(h-45)/.42,base=Y(0);c.clearRect(0,0,w,h);c.strokeStyle='#bccbad';c.beginPath();c.moveTo(20,base);c.lineTo(w-15,base);c.stroke();
 if(state.e.noisy){c.fillStyle='#c6a36a66';c.beginPath();c.moveTo(X(data.t),base);for(let i=0;i<=90;i++){const x=data.t+(4.5-data.t)*i/90;c.lineTo(X(x),Y(StudentTMath.pdf(x,3)));}c.lineTo(X(4.5),base);c.fill();c.strokeStyle=orange;c.setLineDash([3,4]);c.beginPath();c.moveTo(X(data.t),base);c.lineTo(X(data.t),22);c.stroke();c.setLineDash([]);c.fillStyle='#9c7f45';c.font='12px Georgia,serif';c.textAlign='center';c.fillText('t≈1.94',X(data.t),15);}
 c.beginPath();for(let i=0;i<=180;i++){const x=-4.5+i/180*9;i?c.lineTo(X(x),Y(StudentTMath.pdf(x,3))):c.moveTo(X(x),Y(StudentTMath.pdf(x,3)));}c.strokeStyle=orange;c.lineWidth=1.8;c.stroke();c.font='10px Georgia,serif';c.fillStyle='#80906c';c.textAlign='center';for(const x of [-4,-2,0,2,4])c.fillText(String(x),X(x),h-8);canvas.dataset.df='3';canvas.dataset.mean=String(data.mean);canvas.dataset.se=String(data.se);canvas.dataset.p=String(data.p);}
window.TrialStoryGosset={summary,discoveryMarkup,discoveryCopy,comparisonMarkup,comparisonNumbers,mathComparisonMarkup,discovery,dashboardMarkup,paintDashboard};
})();
